mapper.insert:
INSERT INTO artist (artist_name, artist_cover, introduction, gender, country, sort_artist_name, album_count, song_count, update_time) SELECT s.artist_name, s.artist_cover, s.introduction, s.gender, s.country, s.sort_artist_name, 0, 0, CURRENT_TIMESTAMP FROM (VALUES
(#{item.artistName}, #{item.artistCover}, #{item.introduction}, #{item.gender}, #{item.country}, #{item.sortArtistName})
) AS s(artist_name, artist_cover, introduction, gender, country, sort_artist_name) LEFT JOIN artist t ON s.artist_name = t.artist_name WHERE t.artist_name IS NULL

mapper.update:
UPDATE artist
artist_name = #{artistName}, introduction = #{introduction}, gender = #{gender}, country = #{country}, artist_cover = #{artistCover}, enrich_source = #{enrichSource}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
